import{_ as e,c as t,a0 as o,o as n}from"./chunks/framework.BGabeMLJ.js";const c=JSON.parse('{"title":"FAQs as Administrator. Node Management","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faqs/faqs-of-node-management.md","filePath":"guide/faqs/faqs-of-node-management.md"}'),i={name:"guide/faqs/faqs-of-node-management.md"};function s(r,a,d,l,m,u){return n(),t("div",null,a[0]||(a[0]=[o('<h1 id="faqs-as-administrator-node-management" tabindex="-1">FAQs as Administrator. Node Management <a class="header-anchor" href="#faqs-as-administrator-node-management" aria-label="Permalink to &quot;FAQs as Administrator. Node Management&quot;">​</a></h1><h3 id="what-are-the-main-responsibilities-of-a-node-administrator" tabindex="-1">What are the main responsibilities of a Node administrator? <a class="header-anchor" href="#what-are-the-main-responsibilities-of-a-node-administrator" aria-label="Permalink to &quot;What are the main responsibilities of a Node administrator?&quot;">​</a></h3><p>A Node administrator&#39;s main responsibilities include running and monitoring approved analyses, managing local data stores, and defining data stores according to the available data types. For detailed responsibilities, refer to <a href="/guide/admin/node-management.html">node management</a>.</p><h3 id="how-do-i-set-up-a-data-store" tabindex="-1">How do I set up a data store? <a class="header-anchor" href="#how-do-i-set-up-a-data-store" aria-label="Permalink to &quot;How do I set up a data store?&quot;">​</a></h3><p>Setting up a data store involves an initial configuration during the Node installation to enable the <strong>Node Data Store</strong> service. First, refer to <a href="/guide/deployment/node-installation.html#optional-node-data-store">Node installation| Node Data Store</a> for guidance. Once the installation is successfully completed, you can configure storage solutions like S3 buckets and FHIR servers through the Node UI. For managing your data store, consult <a href="/guide/admin/data-store-management.html">Data Store Management</a>.</p><ul><li>To set up a <strong>FHIR server</strong>, <em>Flame</em> enables you to deploy your own server from scratch during the Node installation.</li><li>To set up a <strong>S3 bucket</strong> on Seaweed, refer to <a href="/guide/admin/bucket-setup-for-data-store.html">bucket Setup for Data Store</a>.</li></ul><h3 id="how-do-i-execute-an-analysis-on-a-node" tabindex="-1">How do I execute an analysis on a node? <a class="header-anchor" href="#how-do-i-execute-an-analysis-on-a-node" aria-label="Permalink to &quot;How do I execute an analysis on a node?&quot;">​</a></h3><p>Once an analysis was approved and a data Store was configured, the Node UI on the Analyses field display a tabular section where you can find your project and on the &quot;Toogle Analysis&quot; you can start manually your analysis. Refer to <a href="/guide/admin/analysis-execution.html">analysis execution</a>.</p>',8)]))}const f=e(i,[["render",s]]);export{c as __pageData,f as default};
